#!/usr/bin/env python3
"""
Round 137b (culprits), 2 October 2026. Needs round 136b.

Fish decline: fished-down stocks and the Living Planet populations.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 137b (2 October)\n\nNeeds round 136b. Tiles patch round137b_tiles.py beside it. No app.js?v= bump.\n\n- Fish decline (asked 2 October), under Biodiversity loss > Fish and under\n  Oceans > Every human impact together > Fish decline (tagged not counted):\n  - fish_stocks (route country): each country shaded by the share of the\n    stocks assessed in its waters whose latest B/Bmsy is under 1; every count\n    and every stock in the box. Tiles fish_stocks.py reads the newest RAM\n    Legacy Stock Assessment Database from Zenodo (CC BY 4.0). Stocks RAM gives\n    to no single country are listed in fish/ram_build.json.\n  - lpi_populations (geojsonlive): every population in ZSL and WWF's public\n    Living Planet Database at its place, every field, its counts, first and\n    last counted years and the change between them; coloured by system,\n    filtered by class. Its download is behind an agreement form: the owner\n    downloads it and uploads it to tiles lpi/download/; tiles\n    lpi_populations.py builds from there.\n\n"]


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round137b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 136b" not in h.read_text(encoding="utf-8"):
        sys.exit("round137b: round 136b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round137b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", "map/index.html", check=False)
            sys.exit("round137b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round137b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


DIFF = ''

if __name__ == "__main__":
    main()
